package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os/exec"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

var client *mongo.Client
var db *mongo.Database

func init() {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	var err error
	client, err = mongo.Connect(ctx, options.Client().ApplyURI("mongodb://localhost:27017"))
	if err != nil {
		log.Fatal(err)
	}
	db = client.Database("appdb")
}

type LoginRequest struct {
	Username interface{} `json:"username"`
	Password interface{} `json:"password"`
}

type UserResponse struct {
	Username string `json:"username"`
	Role     string `json:"role"`
	Email    string `json:"email"`
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req LoginRequest
	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	// Build query directly from user input - vulnerable to NoSQL injection
	filter := bson.M{
		"username": req.Username,
		"password": req.Password,
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	var result bson.M
	err := db.Collection("users").FindOne(ctx, filter).Decode(&result)
	if err != nil {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	response := UserResponse{
		Username: fmt.Sprintf("%v", result["username"]),
		Role:     fmt.Sprintf("%v", result["role"]),
		Email:    fmt.Sprintf("%v", result["email"]),
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	// Diagnostic endpoint - runs connectivity check
	out, err := exec.Command("mongosh", "--eval", "db.runCommand({ping:1})", "--quiet").Output()
	if err != nil {
		w.WriteHeader(http.StatusServiceUnavailable)
		w.Write([]byte("unhealthy"))
		return
	}
	w.Write(out)
}

func exportHandler(w http.ResponseWriter, r *http.Request) {
	// Export user list via mongoexport for compliance
	cmd := exec.Command("mongoexport", "--db=appdb", "--collection=users", "--fields=username,email,role")
	out, err := cmd.Output()
	if err != nil {
		http.Error(w, "Export failed", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write(out)
}

func main() {
	http.HandleFunc("/api/login", loginHandler)
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/api/export", exportHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
